use anyhow::Context;
use chrono::Local;
use kiln_core::Schedule;

use crate::cli::{FiringsArgs, FiringsCommand, ImportArgs};

pub fn run(args: FiringsArgs) -> anyhow::Result<()> {
    match args.command {
        FiringsCommand::Import(a) => import(a),
    }
}

fn import(args: ImportArgs) -> anyhow::Result<()> {
    let text = std::fs::read_to_string(&args.path)
        .with_context(|| format!("reading {}", args.path.display()))?;
    let name = args
        .path
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("imported");
    let schedule = match Schedule::from_csv(&name, &text) {
        Ok(s) => s,
        Err(e) if args.dry_run => {
            eprintln!("{}: {e}", args.path.display());
            std::process::exit(1);
        }
        Err(e) => return Err(e.into()),
    };
    if args.dry_run {
        println!("{}: ok ({} segments)", args.path.display(), schedule.segments.len());
        return Ok(());
    }
    let total = schedule.duration();
    println!(
        "{}  ({} segments, total {}h{:02}m)",
        schedule.name.to_string(),
        schedule.segments.len(),
        total.num_hours(),
        total.num_minutes() % 60
    );
    for (i, s) in schedule.segments.iter().enumerate() {
        println!(
            "  {:>2}. {:>5} °C/h -> {:>5} °C  hold {:>3} min",
            i + 1,
            s.rate_c_per_h,
            s.target_c,
            s.hold_min
        );
    }
    println!("ETA {}", schedule.eta_from(Local::now()).format("%a %H:%M"));
    Ok(())
}

